/**
 * Equivalence probe: compares the original double[] cumulative selection
 * against the refactored Species + WeightedSelector path, using identically
 * seeded RNGs. Any difference in draw count would desync the RNGs and surface
 * as a sequence mismatch.
 */
public class Probe {
    static double[] running(double[] t){ for(int i=0;i<t.length-1;i++) t[i+1]+=t[i]; return t; }

    public static void main(String[] a){
